#pragma clang riscv intrinsic zvvm_vector

#include <riscv_vector.h>

// IME (Zvvm) OFP8 vector types: vfloat8e4m3{mf8..m8,m16}_t and
// vfloat8e5m2{...}_t. LLVM IR has no FP8 type, so they lower to the i8
// container (<vscale x N x i8>; m16 is the byte-typed 2-field tuple). The
// generic RVV utilities (vget/vset/vcreate/vundefined/vlmul_ext/vlmul_trunc/
// vreinterpret) and the m16 pair/unpair cover them.

