// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    ret <vscale x 1 x i8> [[V]]
//
vfloat8e4m3mf8_t test_pass_e4m3mf8(vfloat8e4m3mf8_t v) { return v; }

