// Inline asm: the "vr" / "=vr" constraints accept the OFP8 types (the
// FlashAttention kernel's narrow_to_e4m3 / Zvfofp8min pattern).
// CHECK-LABEL: define dso_local <vscale x 8 x i8> @test_asm_narrow(
// CHECK-SAME: <vscale x 4 x bfloat> [[X:%.*]], i64 noundef [[VL:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[TMP0:%.*]] = call <vscale x 8 x i8> asm "vsetvli x0,$2,e8,mf2,ta,ma\0A\09vfncvtbf16.sat.f.f.w $0,$1", "=^vr,^vr,r"(<vscale x 4 x bfloat> [[X]], i64 [[VL]]) #[[ATTR2:[0-9]+]], !srcloc {{![0-9]+}}
// CHECK-NEXT:    ret <vscale x 8 x i8> [[TMP0]]
//
vfloat8e4m3m1_t test_asm_narrow(vbfloat16m1_t x, size_t vl) {
  vfloat8e4m3m1_t y;
  __asm__("vsetvli x0,%2,e8,mf2,ta,ma\n\tvfncvtbf16.sat.f.f.w %0,%1"
          : "=vr"(y)
          : "vr"(x), "r"(vl));
  return y;
}

// CHECK-LABEL: define dso_local <vscale x 32 x i8> @test_asm_m4(
// CHECK-SAME: <vscale x 32 x i8> [[A:%.*]], <vscale x 32 x i8> [[B:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[TMP0:%.*]] = call <vscale x 32 x i8> asm "vmv4r.v $0, $1", "=^vr,^vr"(<vscale x 32 x i8> [[B]]) #[[ATTR2]], !srcloc {{![0-9]+}}
// CHECK-NEXT:    ret <vscale x 32 x i8> [[TMP0]]
//
vfloat8e5m2m4_t test_asm_m4(vfloat8e5m2m4_t a, vfloat8e4m3m4_t b) {
  vfloat8e5m2m4_t r;
  __asm__("vmv4r.v %0, %1" : "=vr"(r) : "vr"(b));
  (void)a;
  return r;
}
